"""Tests for GridSynthRewrite (Ross–Selinger gridsynth)."""

import math
import random
from concurrent.futures import ThreadPoolExecutor

import mpmath
import pytest
from symengine import Symbol, pi

import mimiqcircuits as mc
from mimiqcircuits import _core
from mimiqcircuits.decomposition import (
    CliffordTBasis,
    GridSynthRewrite,
    decompose,
    decompose_step,
)
from mimiqcircuits.decomposition.rules import gridsynth as gs

OUTPUT_TYPES = (mc.GateH, mc.GateS, mc.GateSDG, mc.GateZ, mc.GateT, mc.GateX)

# Errors down to 1e-15 over ~150 gates cannot be checked with float64 gate
# matrices, so the words are multiplied out at 256 bits with mpmath (installed
# with sympy), in a private context to leave the global mpmath state alone.
_CTX = mpmath.MPContext()
_CTX.prec = 256


def _gate_matrix(op):
    ctx = _CTX
    s = 1 / ctx.sqrt(2)
    if isinstance(op, mc.GateH):
        return ctx.matrix([[s, s], [s, -s]])
    if isinstance(op, mc.GateT):
        return ctx.matrix([[1, 0], [0, ctx.expjpi(ctx.mpf(1) / 4)]])
    if isinstance(op, mc.GateS):
        return ctx.matrix([[1, 0], [0, ctx.j]])
    if isinstance(op, mc.GateSDG):
        return ctx.matrix([[1, 0], [0, -ctx.j]])
    if isinstance(op, mc.GateZ):
        return ctx.matrix([[1, 0], [0, -1]])
    if isinstance(op, mc.GateX):
        return ctx.matrix([[0, 1], [1, 0]])
    raise AssertionError(f"unexpected gate {op}")


def _circuit_matrix(c):
    U = _CTX.eye(2)
    for inst in c:
        U = _gate_matrix(inst.operation) * U
    return U


def _phase_distance(U, V):
    """min_φ ‖U − e^{iφ}V‖ in operator norm. For unitaries the optimal phase is
    the argument of tr(V†U); the 2×2 largest singular value has a closed form."""
    ctx = _CTX
    Vh = V.transpose_conj()
    t = Vh * U
    phi = ctx.arg(t[0, 0] + t[1, 1])
    D = U - ctx.expj(phi) * V
    f = sum(abs(D[i, j]) ** 2 for i in range(2) for j in range(2))
    d = abs(D[0, 0] * D[1, 1] - D[0, 1] * D[1, 0]) ** 2
    return ctx.sqrt((f + ctx.sqrt(max(f**2 - 4 * d, 0))) / 2)


def _error(lmbda, c):
    ctx = _CTX
    theta = ctx.mpf(lmbda)
    V = ctx.matrix([[ctx.expj(-theta / 2), 0], [0, ctx.expj(theta / 2)]])
    return float(_phase_distance(_circuit_matrix(c), V))


def _tcount(c):
    return sum(isinstance(i.operation, (mc.GateT, mc.GateTDG)) for i in c)


def _synth(lmbda, epsilon=1e-10, seed=0):
    return decompose_step(
        mc.GateRZ(lmbda), GridSynthRewrite(epsilon=epsilon, seed=seed)
    )


_CODES = {
    mc.GateH: "H",
    mc.GateS: "S",
    mc.GateSDG: "D",
    mc.GateZ: "Z",
    mc.GateT: "T",
    mc.GateX: "X",
}


def _code(c):
    return "".join(_CODES[type(i.operation)] for i in c)


class TestConstructor:
    def test_defaults(self):
        rule = GridSynthRewrite()
        assert rule.epsilon == 1e-10
        assert rule.seed == 0
        assert GridSynthRewrite(epsilon=1e-3).epsilon == 1e-3

    @pytest.mark.parametrize(
        "epsilon", [0, 1, -1e-3, 2.0, math.nan, math.inf, 9e-101, 5e-324]
    )
    def test_invalid_epsilon(self, epsilon):
        with pytest.raises(ValueError):
            GridSynthRewrite(epsilon=epsilon)

    def test_epsilon_floor(self):
        assert GridSynthRewrite(epsilon=1e-100).epsilon == 1e-100

    @pytest.mark.parametrize("seed", [-1, 2**64])
    def test_invalid_seed(self, seed):
        with pytest.raises(ValueError):
            GridSynthRewrite(seed=seed)

    def test_seed_range(self):
        assert GridSynthRewrite(seed=2**64 - 1).seed == 2**64 - 1

    def test_invalid_types(self):
        with pytest.raises(TypeError):
            GridSynthRewrite(seed=1.7)
        with pytest.raises(TypeError):
            GridSynthRewrite(epsilon="0.1")

    def test_hashable(self):
        assert GridSynthRewrite() == GridSynthRewrite()
        assert hash(GridSynthRewrite()) == hash(GridSynthRewrite())


class TestMatches:
    def test_matches(self):
        rule = GridSynthRewrite()
        assert rule.matches(mc.GateRZ(0.123))
        assert rule.matches(mc.GateRZ(pi))
        assert not rule.matches(mc.GateRZ(Symbol("theta")))
        assert not rule.matches(mc.GateRX(0.1))
        assert not rule.matches(mc.GateRY(0.1))
        assert not rule.matches(mc.GateU(0.1, 0.2, 0.3))
        assert not rule.matches(mc.GateH())
        assert not rule.matches(mc.GateCX())

    def test_non_matching_raises(self):
        with pytest.raises(mc.DecompositionError):
            GridSynthRewrite().decompose_step(mc.GateRX(0.1), [0], [], [])

    @pytest.mark.parametrize("lmbda", [math.nan, math.inf, -math.inf])
    def test_non_finite_angle_raises(self, lmbda):
        with pytest.raises(ValueError):
            GridSynthRewrite().decompose_step(mc.GateRZ(lmbda), [0], [], [])
        with pytest.raises(ValueError):
            decompose(mc.Circuit().push(mc.GateRZ(lmbda), 0), CliffordTBasis())


class TestSynthesis:
    @pytest.mark.parametrize("epsilon", [1e-2, 1e-4, 1e-6, 1e-8, 1e-10, 1e-12, 1e-15])
    def test_error_bound_and_gate_set(self, epsilon):
        rng = random.Random(1234)
        for _ in range(5):
            lmbda = 4 * math.pi * (rng.random() - 0.5)
            c = _synth(lmbda, epsilon)
            assert _error(lmbda, c) <= epsilon
            assert all(isinstance(i.operation, OUTPUT_TYPES) for i in c)
            assert all(i.qubits == (0,) for i in c)

    @pytest.mark.parametrize("lmbda", [100.0, -57.3, 1e3])
    def test_large_angles(self, lmbda):
        assert _error(lmbda, _synth(lmbda, 1e-8)) <= 1e-8

    @pytest.mark.parametrize("k", range(-8, 9))
    def test_exact_angles(self, k):
        lmbda = k * math.pi / 4
        c = _synth(lmbda)
        assert _tcount(c) == (1 if k % 2 else 0)
        assert len(c) <= 2
        assert _error(lmbda, c) <= 1e-10

    def test_zero_angle_is_empty(self):
        assert len(_synth(0.0)) == 0

    @pytest.mark.parametrize(
        "lmbda, epsilon, expected",
        [
            # T-counts from pygridsynth 1.2.0 (up_to_phase=True) for the same
            # float angles and tolerances.
            (0.1, 1e-3, 35), (1.2345, 1e-3, 33), (3.0, 1e-3, 32), (-2.5, 1e-3, 31),
            (0.1, 1e-5, 55), (2.0, 1e-5, 50), (0.001, 1e-5, 53), (-2.5, 1e-5, 54),
            (0.5, 1e-10, 102), (1.0, 1e-10, 105), (2.0, 1e-10, 101), (-0.7, 1e-10, 105),
            (0.1, 1e-15, 151), (1.0, 1e-15, 150), (1.2345, 1e-15, 155), (3.0, 1e-15, 153),
        ],
    )  # fmt: skip
    def test_tcount_matches_pygridsynth(self, lmbda, epsilon, expected):
        assert _tcount(_synth(lmbda, epsilon)) == expected

    @pytest.mark.parametrize("epsilon", [1e-4, 1e-8, 1e-12])
    def test_tcount_scaling(self, epsilon):
        assert abs(_tcount(_synth(0.7, epsilon)) - 3 * math.log2(1 / epsilon)) <= 12

    def test_deterministic(self):
        c1 = _synth(0.4321, 1e-9)
        with gs._GRIDSYNTH_CACHE_LOCK:
            gs._GRIDSYNTH_CACHE.clear()
        c2 = _synth(0.4321, 1e-9)
        assert c1 == c2

        c3 = _synth(0.4321, 1e-9, seed=7)
        assert _error(0.4321, c3) <= 1e-9

    def test_target_qubit(self):
        c = GridSynthRewrite(epsilon=1e-3).decompose_step(mc.GateRZ(0.3), [4], [], [])
        assert len(c) > 0
        assert all(i.qubits == (4,) for i in c)


