@pytest.mark.parametrize("lmbda, epsilon, seed, expected", JULIA_REFERENCE)
def test_julia_parity(lmbda, epsilon, seed, expected):
    assert _code(_synth(lmbda, epsilon, seed)) == expected


def test_thread_safety():
    cases = [(0.1 + 0.37 * i, eps) for i in range(6) for eps in (1e-4, 1e-9, 1e-14)]

    def run(case):
        lmbda, epsilon = case
        return _core.gridsynth(lmbda, epsilon)

    # The rule's cache is bypassed so every thread really synthesizes.
    serial = [run(case) for case in cases]
    with ThreadPoolExecutor(max_workers=6) as pool:
        concurrent = list(pool.map(run, cases))
    assert concurrent == serial


def test_rule_concurrent():
    rule = GridSynthRewrite(epsilon=1e-9, seed=3)
    angles = [0.05 + 0.29 * i for i in range(24)]

    def run(lmbda):
        return _code(rule.decompose_step(mc.GateRZ(lmbda), [0], [], []))

    def clear_cache():
        with gs._GRIDSYNTH_CACHE_LOCK:
            gs._GRIDSYNTH_CACHE.clear()

    clear_cache()
    serial = [run(a) for a in angles]
    clear_cache()
    # Every angle is requested twice, so threads race on the same cache keys.
    with ThreadPoolExecutor(max_workers=8) as pool:
        concurrent = list(pool.map(run, angles * 2))
    assert concurrent == serial * 2


class TestCore:
    def test_word_alphabet(self):
        assert set(_core.gridsynth(0.3, 1e-6)) <= set("HSTX")

    @pytest.mark.parametrize("theta", [math.inf, -math.inf, math.nan])
    def test_non_finite_angle(self, theta):
        with pytest.raises(ValueError):
            _core.gridsynth(theta, 1e-3)

    @pytest.mark.parametrize("epsilon", [0.0, 1.0, -1e-3, math.nan])
    def test_invalid_epsilon(self, epsilon):
        with pytest.raises(ValueError):
            _core.gridsynth(0.1, epsilon)

    @pytest.mark.parametrize("seed", [-1, 2**64])
    def test_invalid_seed(self, seed):
        with pytest.raises(OverflowError):
            _core.gridsynth(0.1, 1e-3, seed)
